def f(g):
    h,w=len(g),len(g[0])
    bg=Counter(sum(g,[])).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    out=[[bg]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and not seen[r][c]:
                col=g[r][c]; q=deque([(r,c)]); seen[r][c]=True; comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and not seen[na][nb] and g[na][nb]==col:
                            seen[na][nb]=True; q.append((na,nb))
                cs=max(b for _,b in comp)
                stay=set((a,b) for a,b in comp if b==cs)
                occ={(a,b) for a,b in stay}
                for a,b in comp:
                    if (a,b) in stay: continue
                    nb=b+1
                    if nb>w-1: stay.add((a,b)); continue
                    if (a,nb) in occ: stay.add((a,b))
                    else: occ.add((a,nb)); occ.discard((a,b))
                for a,b in occ: out[a][b]=col
    return out
